// GET /api/jisho?q=<word> — dictionary lookup for the Add Vocab page.
//
// ("jisho" 辞書 just means "dictionary", so the route name still fits even
// though jisho.org is no longer the primary source. The path is unchanged so
// worker.js's ROUTES table and js/add-vocab.js keep working as-is.)
//
// WHY THIS IS NOT jisho.org ANY MORE — measured, not guessed (2026-08-16):
// jisho.org is unreachable from Cloudflare Workers. Every request from a real
// Worker (tested via `wrangler dev --remote`, so a genuine Cloudflare colo)
// comes back as HTTP 525 "SSL handshake failed", generated by Cloudflare
// itself, in ~165ms — the request never reaches jisho. Verified against
// https://jisho.org, https://www.jisho.org, plain http://, and with browser
// User-Agent/Accept headers: all 525. From an ordinary IP the same URL answers
// 200 in ~0.4s, and https://example.com answers 200 from the same Worker, so
// this is neither our egress nor jisho being down — jisho.org is blocking
// Cloudflare's shared Worker egress IPs at the TLS layer (a normal
// anti-scraping measure; their API is unofficial and they ask people not to
// hammer it). jisho.org is on ZoneEdit nameservers, so this is NOT the
// "fetching a Cloudflare zone from a Worker" trap — it is a deliberate block,
// and nothing we can set on fetch() gets around it.
//
// Jotoba (https://jotoba.de, open-source, JMdict-backed — the same dictionary
// data jisho.org uses) IS reachable: 5/5 test words returned 200 with real
// results in 35-64ms from the edge. So it is the primary source now, with
// jisho.org kept as a fallback purely as free insurance in case that block is
// ever lifted — it costs nothing on the happy path, since it is only tried
// after Jotoba has already failed.
//
// The response shape is UNCHANGED regardless of which source answered, so
// js/add-vocab.js needs no knowledge of any of this. Both mappers are
// allowlist projections — same discipline as _lib/kv.js#toPublic(): never
// forward third-party fields we haven't looked at.

import { json, err } from './_lib/http.js';
import { checkRateLimit } from './_lib/ratelimit.js';

const MAX_QUERY_LENGTH = 64;
const MAX_RESULTS = 12;
const MAX_SENSES = 5;
const LOOKUP_TIMEOUT_MS = 8000;

// js/add-vocab.js keys the "usually written in kana" checkbox off this exact
// string (it is jisho.org's wording). Jotoba encodes the same fact as the enum
// "UsuallyWrittenInKana", so translate it here rather than teaching the client
// about a second spelling.
const KANA_ALONE_TAG = 'Usually written using kana alone';
const JOTOBA_MISC_TAGS = { UsuallyWrittenInKana: KANA_ALONE_TAG };

export async function onRequestGet({ request, env, data }) {
  const q = new URL(request.url).searchParams.get('q')?.trim();
  if (!q) return err(400, 'bad_request', 'Enter a word to look up.');
  if (q.length > MAX_QUERY_LENGTH) {
    return err(400, 'bad_request', 'That search is too long.');
  }

  const { allowed, retryAfter } = await checkRateLimit(env, data.user.id, 'jisho');
  if (!allowed) {
    return err(429, 'rate_limited', `Too many lookups — try again in ${retryAfter}s.`);
  }

  // Primary, then fallback. Each returns null on failure (already logged) so a
  // dead source degrades to the next one instead of failing the request.
  const jotobaResults = await lookupJotoba(q);
  if (jotobaResults) return json({ source: 'jotoba', results: jotobaResults });

  const jishoResults = await lookupJisho(q);
  if (jishoResults) return json({ source: 'jisho', results: jishoResults });

  return err(
    502,
    'lookup_failed',
    'The dictionary is not responding right now. You can still add the word manually.',
  );
}

/**
 * Jotoba's word search. POST + JSON body, so Cloudflare's `cf.cacheTtl*`
 * options don't apply (they're GET/HEAD only) — acceptable, since it answers
 * in well under 100ms from the edge.
 *
 * @returns {Promise<Array|null>} mapped entries, or null if the lookup failed
 */
async function lookupJotoba(q) {
  let res;
  try {
    res = await fetch('https://jotoba.de/api/search/words', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ query: q, language: 'English', no_english: false }),
      signal: AbortSignal.timeout(LOOKUP_TIMEOUT_MS),
    });
  } catch (e) {
    console.error('[jisho] jotoba fetch threw', e);
    return null;
  }

  if (!res.ok) {
    console.error(`[jisho] jotoba returned HTTP ${res.status}`);
    return null;
  }

  let body;
  try {
    body = await res.json();
  } catch (e) {
    console.error('[jisho] jotoba response was not valid JSON', e);
    return null;
  }

  const words = Array.isArray(body?.words) ? body.words : [];
  // A 200 with zero results is a legitimate "no such word" answer for a real
  // query, but it's also what a throttled Jotoba returns. Treat empty as a
  // miss so the jisho fallback still gets a chance; an genuinely unknown word
  // then just ends up with the same empty list from the fallback.
  if (words.length === 0) return null;

  return words.slice(0, MAX_RESULTS).map(toJotobaEntry);
}

function toJotobaEntry(word) {
  const kanji = typeof word?.reading?.kanji === 'string' ? word.reading.kanji : null;
  const kana = typeof word?.reading?.kana === 'string' ? word.reading.kana : '';

  return {
    slug: kanji || kana || null,
    isCommon: word?.common === true,
    // Jotoba exposes JLPT on kanji entries, not on word entries. The dropdown
    // renders this as an optional badge, so an empty list just omits it.
    jlpt: [],
    forms: [{ word: kanji, reading: kana }],
    senses: Array.isArray(word?.senses)
      ? word.senses.slice(0, MAX_SENSES).map((s) => ({
          english: Array.isArray(s?.glosses) ? s.glosses.filter((g) => typeof g === 'string') : [],
          partsOfSpeech: Array.isArray(s?.pos)
            ? s.pos.map(posLabel).filter((p) => typeof p === 'string')
            : [],
          tags: miscToTags(s?.misc),
        }))
      : [],
  };
}

/**
 * Jotoba's part-of-speech entries are either a bare string ("Noun") or a
 * single-key object that may nest one level: {"Verb":"Ichidan"} or
 * {"Verb":{"Godan":"RuIrreg"}}. Flattened to a readable label for display and
 * for custom_vocab.part_of_speech.
 */
function posLabel(pos) {
  if (typeof pos === 'string') return pos;
  if (!pos || typeof pos !== 'object') return null;

  const [key, value] = Object.entries(pos)[0] || [];
  if (!key) return null;
  if (typeof value === 'string') return `${key} (${value})`;
  if (value && typeof value === 'object') {
    const [inner, innerValue] = Object.entries(value)[0] || [];
    if (!inner) return key;
    return `${key} (${inner}${typeof innerValue === 'string' ? ` ${innerValue}` : ''})`;
  }
  return key;
}

/** Jotoba `misc` is a single enum string (or absent); jisho used a tag array. */
function miscToTags(misc) {
  const list = Array.isArray(misc) ? misc : misc ? [misc] : [];
  return list.filter((m) => typeof m === 'string').map((m) => JOTOBA_MISC_TAGS[m] || m);
}

/**
 * jisho.org's unofficial API — currently blocked from Cloudflare Workers (see
 * the file header), kept as a fallback in case that changes.
 *
 * @returns {Promise<Array|null>} mapped entries, or null if the lookup failed
 */
async function lookupJisho(q) {
  let res;
  try {
    res = await fetch(`https://jisho.org/api/v1/search/words?keyword=${encodeURIComponent(q)}`, {
      signal: AbortSignal.timeout(LOOKUP_TIMEOUT_MS),
      // Cache successes only. Plain `cacheTtl` + `cacheEverything` would cache
      // a transient 502 for the full 24h too, turning one hiccup into a day of
      // failures for that query at that colo.
      cf: { cacheTtlByStatus: { '200-299': 86400, '300-599': 0 } },
    });
  } catch (e) {
    console.error('[jisho] jisho.org fetch threw', e);
    return null;
  }

  if (!res.ok) {
    console.error(`[jisho] jisho.org returned HTTP ${res.status}`);
    return null;
  }

  let body;
  try {
    body = await res.json();
  } catch (e) {
    console.error('[jisho] jisho.org response was not valid JSON', e);
    return null;
  }

  const entries = Array.isArray(body?.data) ? body.data : [];
  return entries.slice(0, MAX_RESULTS).map(toJishoEntry);
}

function toJishoEntry(entry) {
  return {
    slug: typeof entry?.slug === 'string' ? entry.slug : null,
    isCommon: entry?.is_common === true,
    jlpt: Array.isArray(entry?.jlpt) ? entry.jlpt.filter((j) => typeof j === 'string') : [],
    forms: Array.isArray(entry?.japanese)
      ? entry.japanese.map((f) => ({
          word: typeof f?.word === 'string' ? f.word : null,
          reading: typeof f?.reading === 'string' ? f.reading : '',
        }))
      : [],
    senses: Array.isArray(entry?.senses)
      ? entry.senses.slice(0, MAX_SENSES).map((s) => ({
          english: Array.isArray(s?.english_definitions)
            ? s.english_definitions.filter((e) => typeof e === 'string')
            : [],
          partsOfSpeech: Array.isArray(s?.parts_of_speech)
            ? s.parts_of_speech.filter((p) => typeof p === 'string')
            : [],
          tags: Array.isArray(s?.tags) ? s.tags.filter((t) => typeof t === 'string') : [],
        }))
      : [],
  };
}
